//! Enrols every IPC command in the ACL (plan section 7, "IPC").
//!
//! Declaring an app manifest is what makes Tauri check app commands against
//! capabilities at all; without one, every registered command is callable.
//! Harness commands are enrolled only when the `test-harness` feature is on,
//! and their stale generated permission files are removed otherwise, because
//! tauri-build reads every file in `permissions/autogenerated` and never cleans
//! it. CI checks the production binary for any trace of them.

const COMMANDS: &[&str] = &["frontend_ready", "current_view"];

const HARNESS_COMMANDS: &[&str] = &[
    "frontend_ready",
    "current_view",
    "harness_report",
    "harness_inject",
    // Enrolled but granted to no capability: the denied-call probe.
    "harness_denied_probe",
];

fn main() {
    let harness = std::env::var_os("CARGO_FEATURE_TEST_HARNESS").is_some();
    if !harness {
        remove_stale_harness_permissions();
    }
    let commands = if harness { HARNESS_COMMANDS } else { COMMANDS };
    let attributes = tauri_build::Attributes::new()
        .app_manifest(tauri_build::AppManifest::new().commands(commands));
    tauri_build::try_build(attributes).expect("tauri-build failed");
}

fn remove_stale_harness_permissions() {
    let Ok(entries) = std::fs::read_dir("permissions/autogenerated") else {
        return;
    };
    for entry in entries.flatten() {
        if entry.file_name().to_string_lossy().starts_with("harness_") {
            std::fs::remove_file(entry.path()).expect("could not remove stale harness permission");
        }
    }
}
